import { useEffect, useState } from "react";
import MapaMexico from "./MapaMexico"; // Componente del mapa de México
import { useTheme } from "./useTheme"; // Hook para manejar el tema (claro/oscuro)
import "./components/Inicio.css"; // Estilos para el componente

function Inicio() {
  const [sismos, setSismos] = useState([]); // Almacena la lista de sismos
  const [menuVisible, setMenuVisible] = useState(false); // Controla si el menú lateral está visible
  const [sismoSeleccionado, setSismoSeleccionado] = useState(null); // Sismo seleccionado en el menú
  const [coordenadas, setCoordenadas] = useState(null); // Coordenadas de visualización en el mapa
  const { theme, toggleTheme } = useTheme(); // Manejo del tema (claro/oscuro)

  // Campos de búsqueda (fecha y magnitud)
  const [fechaFiltro, setFechaFiltro] = useState(""); // Almacena la fecha ingresada
  const [magnitudFiltro, setMagnitudFiltro] = useState(""); // Almacena la magnitud ingresada

  useEffect(() => {
    // Fetch inicial para obtener sismos desde el backend
    fetch("http://localhost:9090/inicio", {
      method: "GET",
      headers: { "Content-Type": "application/json" },
    })
      .then((response) => {
        if (!response.ok) throw new Error("Error en la respuesta del servidor");
        return response.json();
      })
      .then((data) => {
        setSismos(data); // Actualiza la lista de sismos
      })
      .catch((error) => console.error("Error al obtener datos:", error));
  }, []);

  // Maneja el clic en un sismo: lo selecciona y centra en el mapa
  const handleSismoClick = (sismo) => {
    setSismoSeleccionado(sismo);
    setCoordenadas({ lat: sismo.latitud, lng: sismo.longitud });
  };

  // Maneja el filtro de búsqueda por fecha y magnitud
  const handleBuscar = () => {
    const fecha = new Date(fechaFiltro); // Convierte la fecha ingresada a un objeto `Date`
    const magnitud = parseFloat(magnitudFiltro); // Convierte la magnitud ingresada a un número

    // Filtra los sismos según los valores ingresados
    const sismosFiltrados = sismos.filter((sismo) => {
      const fechaSismo = new Date(sismo.fecha);
      return (
        (!isNaN(fecha) ? fechaSismo.getTime() === fecha.getTime() : true) && // Comparación de la fecha
        (!isNaN(magnitud) ? sismo.magnitud >= magnitud : true) // Comparación de la magnitud
      );
    });

    setSismos(sismosFiltrados); // Actualiza la lista de sismos con los resultados del filtro
  };

  return (
    <div className={`container ${theme}`}>
      {/* Switch para cambiar entre tema claro y oscuro */}
      <div className="theme-switch-container">
        <label className="switch">
          <input
            type="checkbox"
            onChange={toggleTheme}
            checked={theme === "dark"}
          />
          <span className="slider round"></span>
        </label>
      </div>

      {/* Contenedor del cuadro de búsqueda */}
      <div className="search-container">
        <input
          type="date"
          value={fechaFiltro}
          onChange={(e) => setFechaFiltro(e.target.value)}
          placeholder="Fecha (dd/mm/aaaa)"
        />
        <input
          type="number"
          value={magnitudFiltro}
          onChange={(e) => setMagnitudFiltro(e.target.value)}
          placeholder="Magnitud mínima"
          min="0"
          step="0.1"
        />
        <button onClick={handleBuscar}>Buscar</button>
      </div>

      {/* Contenedor del mapa */}
      <div className="map-container">
        <MapaMexico coordenadas={coordenadas} theme={theme} />
      </div>

      {/* Menú lateral para mostrar los sismos */}
      <div className={`sidebar ${menuVisible ? "visible" : ""}`}>
        <button className="close-btn" onClick={() => setMenuVisible(false)}>
          &times;
        </button>
        <h2>Menú</h2>
        <ul>
          <li>
            <a href="#sismos">Sismos Recientes</a>
          </li>
        </ul>
        <div className="content">
          <h2 id="sismos">Sismos Recientes</h2>
          <ul className="sismos-list">
            {sismos.map((sismo) => (
              <li
                key={sismo.identificador}
                className={`sismo-item ${
                  sismoSeleccionado === sismo ? "activo" : ""
                }`}
                onClick={() => handleSismoClick(sismo)}
              >
                <strong>{sismo.referenciaLocalizacion}</strong> - Magnitud:{" "}
                {sismo.magnitud}
              </li>
            ))}
          </ul>
          {sismoSeleccionado && (
            <div className="sismo-info">
              <h3>Detalles del Sismo</h3>
              <p>
                <b>Ubicación:</b> {sismoSeleccionado.referenciaLocalizacion}
              </p>
              <p>
                <b>Magnitud:</b> {sismoSeleccionado.magnitud}
              </p>
              <p>
                <b>Fecha:</b> {sismoSeleccionado.fecha} {sismoSeleccionado.hora}
              </p>
              <p>
                <b>Profundidad:</b> {sismoSeleccionado.profundidad} km
              </p>
              <p>
                <b>Latitud:</b> {sismoSeleccionado.latitud},{" "}
                <b>Longitud:</b> {sismoSeleccionado.longitud}
              </p>
              <p>
                <b>Estatus:</b> {sismoSeleccionado.estatus}
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Botón del menú hamburguesa */}
      <button
        className="menu-btn"
        onClick={() => setMenuVisible(!menuVisible)}
      >
        &#9776;
      </button>
    </div>
  );
}

export default Inicio;
